+/* Livebook's own "+ Elixir/+ Block" between-cell affordance, adapted to this document's two
+   real block kinds. A fixed small height at rest (not zero) so hovering never shifts surrounding
+   content — only the buttons themselves fade in. */
+.gramaire__insert-zone {
+  height: 14px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.gramaire__insert-buttons {
+  display: flex;
+  gap: 6px;
+  opacity: 0;
+  transition: opacity 0.1s ease;
+}
+.gramaire__insert-zone:hover .gramaire__insert-buttons {
+  opacity: 1;
+}
